-- Monotonic clock for EVERY backed-up table, including writes outside Service.commit().
CREATE TABLE backup_clock (id TEXT PRIMARY KEY NOT NULL, revision INTEGER NOT NULL);
INSERT INTO backup_clock VALUES ('main',0);
CREATE TABLE cleanup_clock (id TEXT PRIMARY KEY NOT NULL, revision INTEGER NOT NULL);
INSERT INTO cleanup_clock VALUES ('main',0);
CREATE TRIGGER backup_clock_audit_insert AFTER INSERT ON audit BEGIN UPDATE backup_clock SET revision=revision+1 WHERE id='main'; END;
CREATE TRIGGER backup_clock_audit_update AFTER UPDATE ON audit BEGIN UPDATE backup_clock SET revision=revision+1 WHERE id='main'; END;
CREATE TRIGGER backup_clock_audit_delete AFTER DELETE ON audit BEGIN UPDATE backup_clock SET revision=revision+1 WHERE id='main'; END;
