CREATE TRIGGER cleanup_clock_local_admin_sessions_insert AFTER INSERT ON local_admin_sessions WHEN NEW.expires_at<=CAST(strftime('%s','now') AS INTEGER) BEGIN UPDATE cleanup_clock SET revision=revision+1 WHERE id='main'; END;
CREATE TRIGGER cleanup_clock_local_admin_sessions_update AFTER UPDATE ON local_admin_sessions WHEN OLD.expires_at<=CAST(strftime('%s','now') AS INTEGER) OR NEW.expires_at<=CAST(strftime('%s','now') AS INTEGER) BEGIN UPDATE cleanup_clock SET revision=revision+1 WHERE id='main'; END;
CREATE TRIGGER cleanup_clock_local_admin_sessions_delete AFTER DELETE ON local_admin_sessions WHEN OLD.expires_at<=CAST(strftime('%s','now') AS INTEGER) BEGIN UPDATE cleanup_clock SET revision=revision+1 WHERE id='main'; END;
CREATE TRIGGER cleanup_clock_local_admin_attempts_insert AFTER INSERT ON local_admin_attempts WHEN NEW.created_at<strftime('%Y-%m-%dT%H:%M:%fZ','now','-15 minutes') BEGIN UPDATE cleanup_clock SET revision=revision+1 WHERE id='main'; END;
CREATE TRIGGER cleanup_clock_local_admin_attempts_update AFTER UPDATE ON local_admin_attempts WHEN OLD.created_at<strftime('%Y-%m-%dT%H:%M:%fZ','now','-15 minutes') OR NEW.created_at<strftime('%Y-%m-%dT%H:%M:%fZ','now','-15 minutes') BEGIN UPDATE cleanup_clock SET revision=revision+1 WHERE id='main'; END;
CREATE TRIGGER cleanup_clock_local_admin_attempts_delete AFTER DELETE ON local_admin_attempts WHEN OLD.created_at<strftime('%Y-%m-%dT%H:%M:%fZ','now','-15 minutes') BEGIN UPDATE cleanup_clock SET revision=revision+1 WHERE id='main'; END;
CREATE TRIGGER cleanup_clock_cli_sessions_insert AFTER INSERT ON cli_sessions WHEN NEW.expires_at<=(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER)) BEGIN UPDATE cleanup_clock SET revision=revision+1 WHERE id='main'; END;
CREATE TRIGGER cleanup_clock_cli_sessions_update AFTER UPDATE ON cli_sessions WHEN OLD.expires_at<=(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER)) OR NEW.expires_at<=(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER)) BEGIN UPDATE cleanup_clock SET revision=revision+1 WHERE id='main'; END;
CREATE TRIGGER cleanup_clock_cli_sessions_delete AFTER DELETE ON cli_sessions WHEN OLD.expires_at<=(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER)) BEGIN UPDATE cleanup_clock SET revision=revision+1 WHERE id='main'; END;
CREATE TRIGGER cleanup_clock_cli_attempts_insert AFTER INSERT ON cli_attempts WHEN NEW.expires_at<=(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER)) BEGIN UPDATE cleanup_clock SET revision=revision+1 WHERE id='main'; END;
CREATE TRIGGER cleanup_clock_cli_attempts_update AFTER UPDATE ON cli_attempts WHEN OLD.expires_at<=(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER)) OR NEW.expires_at<=(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER)) BEGIN UPDATE cleanup_clock SET revision=revision+1 WHERE id='main'; END;
CREATE TRIGGER cleanup_clock_cli_attempts_delete AFTER DELETE ON cli_attempts WHEN OLD.expires_at<=(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER)) BEGIN UPDATE cleanup_clock SET revision=revision+1 WHERE id='main'; END;
